window.receiveAmeenPayment=async function(closeAfter=false){const id=document.getElementById('ameenDueSelect')?.value,amount=Number(document.getElementById('ameenPayAmount')?.value||0),note=document.getElementById('ameenPayNote')?.value.trim()||'';if(!id||!Number.isFinite(amount)||amount<=0){showToast('Select a due and enter payment amount.',true);return}try{const r=await api('/api/ameen/'+encodeURIComponent(id)+'/payment','POST',{date:state.currentDate,amount,note});if(r.payment){state.ameenPayments=state.ameenPayments||[];const savedPayment={...r.payment,ameenId:r.payment.ameenId||id};state.ameenPayments=[...state.ameenPayments,savedPayment];const due=state.ameenEntries.find(e=>e.id===id);if(due){due.paid=Number(due.paid||0)+Number(savedPayment.amount||0);due.pending=Number(r.remaining||0)}}if(closeAfter)state.modal=null;render();}catch(e){showToast('Ameen Receipt — Not saved. '+e.message,true)}};
