window.removeGenericPayment=async function(cardId,bookingId,paymentId){if(!confirm('Remove this receipt? The linked due will become pending again.'))return;try{await api('/api/special-card-payment/'+encodeURIComponent(cardId)+'/'+encodeURIComponent(bookingId)+'/'+encodeURIComponent(paymentId),'DELETE');await loadDayData(state.currentDate);render();showToast('Receipt removed.')}catch(e){showToast(e.message,true)}};
