async function saveHandoverConfirmed(){const short=Number(document.getElementById('shortInput')?.value||0),excess=Number(document.getElementById('excessInput')?.value||0),remark=(document.getElementById('mismatchRemark')?.value||'').trim();if(short>0&&excess>0){showToast('Enter either Cash Short or Excess Cash, not both.',true);return}const payload={date:state.currentDate,cashShort:short,excessCash:excess,remark};if(isManagementUser())payload.username=state.selectedUser;try{await api('/api/handover','POST',payload);await loadDayData(state.currentDate);render();setTimeout(()=>{const badge=document.querySelector('.side-stack .badge.ok');if(badge)badge.scrollIntoView({block:'nearest'})},30)}catch(e){showToast('Handover — Not saved. '+e.message,true)}}
window.saveHandover=async function(){if(!state.patientCountEntered){state.modal={kind:'handoverPatient'};render();setTimeout(()=>document.getElementById('patientModalInput')?.focus(),30);return}await saveHandoverConfirmed()}
window.loadEntryManager=async function(){
  const el=document.getElementById('entryManager'); if(!el)return;
  el.innerHTML='<div class="loading">Loading entries…</div>';
  try{
    const {from,to}=reportRange();
    const q=new URLSearchParams({from,to,locationId:state.entryManagerLocation,username:state.reportUser});
    const d=await api('/api/management-summary?'+q.toString());
    const rows=[];
    (d.entries||[]).forEach(e=>{const c=catById(e.catId);if(state.entryManagerCategory!=='all'&&e.catId!==state.entryManagerCategory)return;rows.push({id:e.id,kind:'entry',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:c.name,person:e.person||'—',amount:e.amount,note:e.note||''})});
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__online__') (d.onlineEntries||[]).forEach(e=>rows.push({id:e.id,kind:'online',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Online',person:e.transferor||'—',amount:e.amount,note:e.note||''}));
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__refund__') (d.manualRefundEntries||[]).forEach(e=>rows.push({id:e.id,kind:'refund',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Manual Refund',person:e.patientName||'—',amount:e.amount,note:[e.labNo,e.note].filter(Boolean).join(' | ')}));
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__ameen__') (d.ameenBookings||[]).forEach(e=>rows.push({id:e.id,kind:'ameen',month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Ameen Booking / Due',person:'—',amount:e.amount,note:(e.note||'')+' | Pending '+money(e.pending)}));
    if(state.entryManagerCategory==='all'||state.entryManagerCategory==='__ameenReceipt__') (d.ameenPayments||[]).forEach(e=>rows.push({id:e.id,kind:'ameenPayment',ameenId:e.ameenId,month:state.reportMonth,date:e.date,staff:e.name||e.username,location:locationName(e.locationId),category:'Ameen Receipt',person:'—',amount:e.amount,note:'Against '+fmtDate(e.bookingDate)+(e.note?' | '+e.note:'') }));
    rows.sort((a,b)=>a.date.localeCompare(b.date)||String(a.id).localeCompare(String(b.id)));
    const catOptions=state.categories.filter(c=>c.locationId===state.entryManagerLocation||state.entryManagerLocation==='all').map(c=>`<option value="${escapeHtml(c.id)}" ${state.entryManagerCategory===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('');
    el.innerHTML=`<div class="hint" style="margin-bottom:8px">Filter individual entries by Location and Category. The selected report month and staff filter above remain applicable.</div><div class="filters"><select onchange="setEntryManagerLocation(this.value)"><option value="all" ${state.entryManagerLocation==='all'?'selected':''}>All locations</option>${state.locations.map(l=>`<option value="${l.id}" ${state.entryManagerLocation===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select><select onchange="setEntryManagerCategory(this.value)"><option value="all" ${state.entryManagerCategory==='all'?'selected':''}>All categories</option>${catOptions}<option value="__online__" ${state.entryManagerCategory==='__online__'?'selected':''}>Online</option><option value="__refund__" ${state.entryManagerCategory==='__refund__'?'selected':''}>Manual Refund</option><option value="__ameen__" ${state.entryManagerCategory==='__ameen__'?'selected':''}>Ameen Booking / Due</option><option value="__ameenReceipt__" ${state.entryManagerCategory==='__ameenReceipt__'?'selected':''}>Ameen Receipt</option></select><button class="btn secondary" onclick="loadEntryManager()">Apply Filter</button></div>`+
      `<table><thead><tr><th>Date</th><th>Staff</th><th>Location</th><th>Category</th><th>Person</th><th class="amt">Amount</th><th>Remarks</th><th>Delete</th></tr></thead><tbody>`+
      (rows.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${escapeHtml(r.staff)}</td><td>${escapeHtml(r.location)}</td><td>${escapeHtml(r.category)}</td><td>${escapeHtml(r.person)}</td><td class="amt">${r.kind==='refund'||r.kind==='entry'&&catById((d.entries||[]).find(x=>x.id===r.id)?.catId).type==='expense'?'−':'+'} ${money(r.amount)}</td><td>${escapeHtml(r.note)}</td><td><button class="del-btn" onclick="deleteManagedEntry('${r.kind}','${r.id}'${r.ameenId?`, '${r.ameenId}'`:''})">Remove</button></td></tr>`).join('')||'<tr class="muted-row"><td colspan="8">No entries found.</td></tr>')+
      '</tbody></table>';
  }catch(e){el.innerHTML='<div class="warning">Could not load entries. '+escapeHtml(e.message||'Please refresh.')+'</div>'}
};
window.setEntryManagerLocation=function(v){state.entryManagerLocation=v;state.entryManagerCategory='all';loadEntryManager()};
window.setEntryManagerCategory=function(v){state.entryManagerCategory=v;loadEntryManager()};
window.deleteManagedEntry=async function(kind,id,ameenId){
  if(!confirm('Remove this entry? This action permanently removes the selected transactional record.'))return;
  try{
    if(kind==='entry') await api('/api/entries/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='online') await api('/api/online-entry/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='refund') await api('/api/manual-refund-entry/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='ameen') await api('/api/ameen/'+encodeURIComponent(id)+'?month='+state.reportMonth,'DELETE');
    else if(kind==='ameenPayment') await api('/api/ameen/'+encodeURIComponent(ameenId)+'/payment/'+encodeURIComponent(id),'DELETE');
    await loadEntryManager();
    showToast('Entry removed.');
  }catch(e){showToast(e.message,true)}
};
function reportRange(){if(state.reportMode==='date'&&state.reportDate)return {from:state.reportDate,to:state.reportDate};if(state.reportMode==='range')return {from:state.reportRangeFrom,to:state.reportRangeTo};const from=state.reportMonth+'-01',to=state.reportMonth+'-'+String(dayCountInMonth(state.reportMonth)).padStart(2,'0');return {from,to}}
function reportPeriodLabel(){if(state.reportMode==='date'&&state.reportDate)return fmtDate(state.reportDate);if(state.reportMode==='range'&&state.reportRangeFrom&&state.reportRangeTo)return fmtDate(state.reportRangeFrom)+' — '+fmtDate(state.reportRangeTo);return fmtMonthLabel(state.reportMonth)}
function reportLocationQuery(q){const ids=(state.reportLocations||['all']).filter(x=>x&&x!=='all');q.set('locationIds',ids.join(','));q.set('locationId',ids.length===1?ids[0]:'all');return q}
function reportLocationLabel(){const ids=(state.reportLocations||['all']).filter(x=>x!=='all');return !ids.length?'All locations':ids.length===1?locationName(ids[0]):`${ids.length} locations selected`}
function renderReports(){const selectedLocs=(state.reportLocations||['all']).filter(x=>x!=='all');return `<div class="card"><div class="filters"><strong style="margin-right:4px">Management Report</strong><input type="month" value="${state.reportMonth}" onchange="setReportMonth(this.value)"><select onchange="setReportMode(this.value)"><option value="month" ${state.reportMode==='month'?'selected':''}>This month</option><option value="date" ${state.reportMode==='date'?'selected':''}>Specific date</option><option value="range" ${state.reportMode==='range'?'selected':''}>Date range</option></select>${state.reportMode==='date'?`<input type="date" value="${state.reportDate||todayStr()}" onchange="setReportDate(this.value)">`:state.reportMode==='range'?`<label>From</label><input type="date" value="${state.reportRangeFrom||state.reportMonth+'-01'}" onchange="state.reportRangeFrom=this.value"><label>To</label><input type="date" value="${state.reportRangeTo||todayStr()}" onchange="state.reportRangeTo=this.value"><button class="btn secondary" onclick="applyReportRange()">Apply</button>`:''}${isManagementUser()?`<details class="report-location-picker"><summary>${escapeHtml(reportLocationLabel())}</summary><div class="location-checks"><label><input type="checkbox" ${!selectedLocs.length?'checked':''} onchange="toggleReportLocation('all',this.checked)"> All locations</label>${state.locations.map(l=>`<label><input type="checkbox" value="${escapeHtml(l.id)}" ${selectedLocs.includes(l.id)?'checked':''} onchange="toggleReportLocation('${l.id}',this.checked)"> ${escapeHtml(l.name)}</label>`).join('')}<button type="button" class="btn" onclick="applyReportLocations()">Apply locations</button></div></details><select onchange="setReportUser(this.value)"><option value="all">All staff</option>${state.staff.filter(u=>u.role==='staff'&&(!selectedLocs.length||selectedLocs.includes(u.locationId))).map(u=>`<option value="${escapeHtml(u.username)}" ${state.reportUser===u.username?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select>`:''}<button class="btn secondary no-print" onclick="downloadReportCSV()">Excel (CSV)</button><button class="btn secondary no-print" onclick="printReport()">PDF / Print</button></div><div id="reportBody" class="loading">Loading management report…</div>${isManagementUser()?`<div class="card no-print" style="margin-top:18px"><h3>Data Safety & Demo</h3><div class="hint" style="margin-bottom:10px">A downloadable backup is a complete copy of your Lab-Brain data. The system also keeps automatic snapshots before normal saves.</div><div class="row"><button class="btn secondary" onclick="downloadBackup()">Download Full Backup</button><button class="btn secondary" onclick="loadDemoData()">Load Demo Data</button><button class="btn danger" onclick="removeDemoData()">Remove Demo Data</button><button class="btn secondary" onclick="showBackups()">Backup History</button></div><div id="backupList" style="margin-top:12px"></div></div><div class="card no-print" style="margin-top:18px"><h3>Individual Entry Management</h3><div class="hint" style="margin-bottom:10px">Review and permanently delete individual transactional entries. Use the Location and Category filters below to find the required entries.</div><button class="btn secondary" onclick="loadEntryManager()">Show Entries</button><div id="entryManager" style="margin-top:12px"></div></div>`:''}</div>`}
window.setReportMode=function(v){state.reportMode=v;state.reportPanel='overview';state.reportRevenueCategory='all';state.reportExpenseCategory='all';if(v==='month'){state.reportDate=state.reportMonth+'-01';state.reportRangeFrom=state.reportMonth+'-01';state.reportRangeTo=state.reportMonth+'-'+String(dayCountInMonth(state.reportMonth)).padStart(2,'0')}else if(v==='date'&&!state.reportDate)state.reportDate=todayStr();else if(v==='range'){state.reportRangeFrom=state.reportRangeFrom||state.reportMonth+'-01';state.reportRangeTo=state.reportRangeTo||todayStr()}render();loadReportBody()};window.setReportDate=function(v){if(!v)return;state.reportMode='date';state.reportDate=v;state.reportMonth=monthKeyOf(v);state.reportRangeFrom=v;state.reportRangeTo=v;state.reportPanel='overview';state.reportRevenueCategory='all';state.reportExpenseCategory='all';state.reportDetailFrom=v;state.reportDetailTo=v;state.entryManagerLocation=state.reportLocation;state.entryManagerCategory='all';render();loadReportBody()};window.setReportMonth=function(v){state.reportMonth=v;state.reportMode='month';state.reportDate=v+'-01';state.reportRangeFrom=v+'-01';state.reportRangeTo=v+'-'+String(dayCountInMonth(v)).padStart(2,'0');state.reportPanel='overview';state.reportRevenueCategory='all';state.reportDetailFrom=v+'-01';state.reportDetailTo=v+'-'+String(dayCountInMonth(v)).padStart(2,'0');state.entryManagerLocation=state.reportLocation;state.entryManagerCategory='all';render();loadReportBody()};window.applyReportRange=function(){if(!state.reportRangeFrom||!state.reportRangeTo){showToast('Select both From and To dates.',true);return}if(state.reportRangeFrom>state.reportRangeTo){showToast('From date cannot be after To date.',true);return}state.reportMode='range';state.reportPanel='overview';loadReportBody()};window.toggleReportLocation=function(id,checked){let current=Array.isArray(state.reportLocations)?state.reportLocations:[];let ids=current.filter(x=>x&&x!=='all');const boxes=document.querySelectorAll('.location-checks input[type=checkbox]');const allBox=boxes[0];if(id==='all'){if(checked){state.reportLocations=['all'];boxes.forEach((b,i)=>{if(i>0)b.checked=false})}else{state.reportLocations=[]}return}if(checked){ids=ids.filter(x=>x!==id);ids.push(id);state.reportLocations=ids.length?ids:['all'];if(allBox)allBox.checked=false}else{ids=ids.filter(x=>x!==id);state.reportLocations=ids.length?ids:['all'];if(!ids.length&&allBox)allBox.checked=true}};window.applyReportLocations=function(){const ids=(state.reportLocations||['all']).filter(x=>x!=='all');state.reportLocation=ids.length===1?ids[0]:'all';state.reportUser='all';state.reportPanel='overview';state.reportRevenueCategory='all';state.entryManagerLocation=state.reportLocation;state.entryManagerCategory='all';render();loadReportBody()};window.setReportLocation=function(v){state.reportLocations=v==='all'?['all']:[v];state.reportLocation=v;state.reportUser='all';state.reportPanel='overview';state.reportRevenueCategory='all';state.entryManagerLocation=v;state.entryManagerCategory='all';render();loadReportBody()};window.setReportUser=function(v){state.reportUser=v;state.reportPanel='overview';state.reportRevenueCategory='all';render();loadReportBody()};window.toggleReportPanel=function(v){state.reportPanel=state.reportPanel===v?'overview':v;if(v!=='revenue')state.reportRevenueCategory='all';loadReportBody()};window.setReportRevenueCategory=function(v){state.reportRevenueCategory=v;state.reportPanel='revenue';loadReportBody()};window.openDetailedReport=function(kind){if(!['staff','mismatch'].includes(kind))return;state.reportPanel=kind;if(!state.reportDetailFrom)state.reportDetailFrom=state.reportMode==='range'?state.reportRangeFrom:state.reportMonth+'-01';if(!state.reportDetailTo)state.reportDetailTo=state.reportMode==='range'?state.reportRangeTo:state.reportMonth+'-'+String(dayCountInMonth(state.reportMonth)).padStart(2,'0');loadReportBody()};window.applyDetailedReport=function(){if(!state.reportDetailFrom||!state.reportDetailTo){showToast('Select both From and To dates.',true);return}if(state.reportDetailFrom>state.reportDetailTo){showToast('From date cannot be after To date.',true);return}loadReportBody()};function monthAdd(mk,delta){const [y,m]=mk.split('-').map(Number);const d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function dayCountInMonth(mk){const [y,m]=mk.split('-').map(Number);return new Date(y,m,0).getDate()}
function barSeries(values,max){return values.map(v=>{const pct=max?Math.max(0,Math.min(88,(v.value/max)*88)):0;return `<div class="vbar-wrap" style="--bar-height:${pct}%"><div class="vbar" style="height:${pct}%" title="${escapeHtml(v.label)}: ${escapeHtml(v.display)}"><span class="vbar-value">${escapeHtml(v.display)}</span></div><div class="vbar-label">${escapeHtml(v.label)}</div></div>`}).join('')}
function linearTrendForecast(values){const ys=values.map(Number).filter(Number.isFinite);if(!ys.length)return null;if(ys.length===1)return ys[0];const n=ys.length;let sx=0,sy=0,sxx=0,sxy=0;for(let i=0;i<n;i++){sx+=i;sy+=ys[i];sxx+=i*i;sxy+=i*ys[i]}const den=n*sxx-sx*sx;const slope=den?(n*sxy-sx*sy)/den:0;const intercept=(sy-slope*sx)/n;return Math.max(0,intercept+slope*n)}
async function expectedClosingForecast(metric,currentValue){if(state.reportMode!=='month'||state.reportMonth!==monthKeyOf(todayStr()))return null;const elapsed=Math.max(1,new Date().getDate()),days=dayCountInMonth(state.reportMonth),pace=Math.max(0,Number(currentValue||0))/elapsed*days;const months=[];for(let i=6;i>=1;i--)months.push(monthAdd(state.reportMonth,-i));try{const rows=await Promise.all(months.map(async mk=>{const d=await api('/api/management-summary?'+reportLocationQuery(new URLSearchParams({from:mk+'-01',to:mk+'-'+String(dayCountInMonth(mk)).padStart(2,'0'),username:state.reportUser})));return metric==='patients'?d.patients.reduce((a,x)=>a+Number(x.count||0),0):summarize(reportEntriesWithAmeen(d)).income}));const trend=linearTrendForecast(rows);const adjusted=trend!=null&&trend>0?Math.max(pace,(pace*0.65)+(trend*0.35)):pace;return{value:Math.round(Math.max(0,adjusted)),pace:Math.round(Math.max(0,pace)),trend:trend==null?null:Math.round(Math.max(0,trend))}}catch(e){console.warn('Expected closing forecast unavailable',e);return{value:Math.round(pace),pace:Math.round(pace),trend:null}}}
function reportSpecialTotals(data){const online=(data.online||[]).reduce((a,x)=>a+Number(x.amount||0),0)+(data.onlineEntries||[]).reduce((a,x)=>a+Number(x.amount||0),0);const refund=(data.manualRefunds||[]).reduce((a,x)=>a+Number(x.amount||0),0)+(data.manualRefundEntries||[]).reduce((a,x)=>a+Number(x.amount||0),0);const ameen=(data.ameenBookings||[]).reduce((a,x)=>a+Number(x.amount||0),0);const pending=(data.ameenBookings||[]).reduce((a,x)=>a+Number(x.pending||0),0);const paid=(data.ameenPayments||[]).reduce((a,x)=>a+Number(x.amount||0),0);return{online,refund,ameen,pending,paid}}
function reportEntriesWithAmeen(data){return [...(data.entries||[])]}
