window.setReportExpenseCategory=function(v){state.reportExpenseCategory=v;state.reportExpensePerson='all';state.reportPanel='expense';loadReportBody()};window.setReportExpensePerson=function(v){state.reportExpensePerson=v;state.reportPanel='expense';loadReportBody()};
function locationRows(data){const map={};reportEntriesWithAmeen(data).forEach(e=>{const id=e.locationId||'nmdc-main';map[id]=map[id]||{rev:0,exp:0,patients:0};const c=catById(e.catId);map[id][c.type==='income'?'rev':'exp']+=Number(e.amount||0)});data.patients.forEach(x=>{const id=x.locationId||'nmdc-main';map[id]=map[id]||{rev:0,exp:0,patients:0};map[id].patients+=Number(x.count||0)});return Object.entries(map).map(([id,x])=>`<tr><td>${escapeHtml(locationName(id))}</td><td class="amt pos">${money(x.rev)}</td><td class="amt neg">${money(x.exp)}</td><td class="amt">${x.patients.toLocaleString('en-PK')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="4">No location data.</td></tr>'}
function staffReportRows(data){const map={};reportEntriesWithAmeen(data).forEach(e=>{map[e.username]=map[e.username]||{name:e.name,locationId:e.locationId,rev:0,exp:0,patients:0};const c=catById(e.catId);map[e.username][c.type==='income'?'rev':'exp']+=Number(e.amount||0)});data.patients.forEach(x=>{map[x.username]=map[x.username]||{name:x.username,locationId:x.locationId,rev:0,exp:0,patients:0};map[x.username].patients+=Number(x.count||0)});return Object.values(map).map(x=>`<tr><td>${escapeHtml(x.name)}</td><td>${escapeHtml(locationName(x.locationId))}</td><td class="amt pos">${money(x.rev)}</td><td class="amt neg">${money(x.exp)}</td><td class="amt">${x.patients.toLocaleString('en-PK')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="5">No staff data.</td></tr>'}
function handoverRows(data){return data.handovers.sort((a,b)=>a.date.localeCompare(b.date)).map(h=>`<tr><td>${fmtDate(h.date)}</td><td>${escapeHtml(h.username)}</td><td>${escapeHtml(locationName(h.locationId))}</td><td class="amt">${money(h.calculated)}</td><td class="amt neg">${money(h.cashShort)}</td><td class="amt pos">${money(h.excessCash)}</td><td>${escapeHtml(h.remark||'')}</td></tr>`).join('')||'<tr class="muted-row"><td colspan="7">No handover records.</td></tr>'}
async function downloadFile(url,filename){const headers={};if(state.token)headers.Authorization='Bearer '+state.token;const r=await fetch(url,{headers});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||'Download failed');}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
window.downloadReportCSV=async function(){try{const {from,to}=reportRange();const q=reportLocationQuery(new URLSearchParams({from,to,username:state.reportUser}));await downloadFile('/api/report.csv?'+q.toString(),'lab-brain-report-'+(state.reportMode==='date'?state.reportDate:state.reportMonth)+'.csv');}catch(e){showToast(e.message,true)}};
window.printReport=function(){
  const old=document.querySelector('.print-summary-only');
  if(old) old.remove();
  const side=document.querySelector('.side-stack');
  const main=document.querySelector('.main-stack');
  if(!side||!main){window.print();return}
  const summary=side.querySelector('.summary-card');
  const cards=[...side.children];
  const handover=cards.find(el=>/Cash handover/i.test(el.textContent||''));
  const entries=[...main.children].find(el=>/My entries|Entries/i.test(el.textContent||'')&&el.querySelector('table'));
  if(!summary||!handover||!entries){window.print();return}
  const holder=document.createElement('div');
  holder.className='print-summary-only';
  const top=document.createElement('div');
  top.className='print-top-grid';
  top.appendChild(summary.cloneNode(true));
  top.appendChild(handover.cloneNode(true));
  const entriesClone=entries.cloneNode(true);
  entriesClone.classList.add('print-entries');
  holder.appendChild(top);
  holder.appendChild(entriesClone);
  holder.querySelectorAll('button').forEach(b=>{b.disabled=true;b.removeAttribute('onclick');});
  holder.querySelectorAll('input').forEach(i=>{i.setAttribute('readonly','readonly');});
  document.body.appendChild(holder);
  document.body.classList.add('print-summary-mode');
  const cleanup=()=>{document.body.classList.remove('print-summary-mode');if(holder&&holder.parentNode)holder.remove();window.removeEventListener('afterprint',cleanup);};
  window.addEventListener('afterprint',cleanup);
  setTimeout(()=>window.print(),50);
};
window.downloadBackup=async function(){try{await downloadFile('/api/backup','lab-brain-backup-'+todayStr()+'.json');showToast('Backup downloaded.')}catch(e){showToast(e.message,true)}};
window.loadDemoData=async function(){if(!confirm('Load demo data for testing reports? It will be clearly tracked and can be removed later.'))return;try{const r=await api('/api/demo-data/load','POST',{});showToast(r.message);await loadEverything();state.view='reports';render();loadReportBody()}catch(e){showToast(e.message,true)}};
window.removeDemoData=async function(){if(!confirm('Remove ONLY the demo data previously loaded by Lab-Brain? Your real records are not targeted.'))return;try{const r=await api('/api/demo-data/remove','POST',{});showToast(r.message);await loadEverything();state.view='reports';render();loadReportBody()}catch(e){showToast(e.message,true)}};
window.showBackups=async function(){const el=document.getElementById('backupList');if(!el)return;try{const d=await api('/api/backups');if(!d.backups.length){el.innerHTML='<div class="hint">No automatic snapshots yet. A snapshot is created before the next normal data change.</div>';return}el.innerHTML='<div class="hint" style="margin-bottom:6px">Latest automatic snapshots (newest first):</div>'+d.backups.slice(0,10).map(b=>`<div class="row" style="justify-content:space-between;align-items:center;border-bottom:1px solid var(--line-soft);padding:6px 0"><span>Backup #${b.id} — ${new Date(b.created_at).toLocaleString()}</span><button class="icon-btn" onclick="restoreBackup(${b.id})">Restore</button></div>`).join('')}catch(e){el.innerHTML='<div class="warning">'+escapeHtml(e.message)+'</div>'}};
window.restoreBackup=async function(id){if(!confirm('Restore Backup #'+id+'? Your CURRENT data will first be snapshotted automatically, then this older version will become active.'))return;try{await api('/api/backups/'+id+'/restore','POST',{});localStorage.removeItem('labbrain_token');localStorage.removeItem('roznamcha_token');alert('Backup restored. Please log in again.');location.reload()}catch(e){showToast(e.message,true)}};
window.showTrend=async function(kind,n){const el=document.getElementById('reportBody');if(!el)return;el.innerHTML='<div class="loading">Loading trend…</div>';try{const currentMk=monthKeyOf(todayStr()),months=[];for(let i=n;i>=1;i--)months.push(monthAdd(currentMk,-i));const rows=await Promise.all(months.map(async mk=>{const d=await api('/api/management-summary?'+reportLocationQuery(new URLSearchParams({from:mk+'-01',to:mk+'-'+String(dayCountInMonth(mk)).padStart(2,'0'),username:state.reportUser})));let v=0;if(kind==='patients')v=d.patients.reduce((a,x)=>a+Number(x.count||0),0);else if(kind==='revenue'&&state.reportRevenueCategory!=='all')v=reportEntriesWithAmeen(d).filter(e=>e.catId===state.reportRevenueCategory).reduce((a,e)=>a+Number(e.amount||0),0);else v=summarize(reportEntriesWithAmeen(d))[kind==='revenue'?'income':'expense'];return{value:v,label:fmtMonthLabel(mk),display:kind==='patients'?v.toLocaleString('en-PK'):kind==='revenue'?compactK(v):money(v),tableDisplay:kind==='patients'?v.toLocaleString('en-PK'):money(v)}}));const max=Math.max(1,...rows.map(x=>x.value)),summaryRows=rows.map(r=>`<tr><td>${escapeHtml(r.label)}</td><td class="amt">${escapeHtml(r.tableDisplay)}</td></tr>`).join('');el.innerHTML=`<div class="analysis card"><div class="analysis-head"><div><h3>${kind==='revenue'?'Revenue'+(state.reportRevenueCategory!=='all'?' — '+escapeHtml(catById(state.reportRevenueCategory).name):''):kind==='expense'?'Cash Counter Expenses':'Patient Count'} — Last ${n} Completed Months</h3><div class="hint">Current incomplete month is excluded.</div></div><button class="icon-btn" onclick="loadReportBody()">Back</button></div><div class="vbars trend-bars">${barSeries(rows,max)}</div><table class="trend-values"><thead><tr><th>Month</th><th class="amt">${kind==='patients'?'Patients':'Amount'}</th></tr></thead><tbody>${summaryRows}</tbody></table></div>`}catch(e){console.error(e);el.innerHTML=`<div class="warning">Trend could not be loaded. ${escapeHtml(e.message||'Please try again.')}</div>`}}
let specialLedgerData=null;
async function loadSpecialLedger(){const el=document.getElementById('specialLedgerBody');if(!el)return;el.innerHTML='<div class="loading">Loading ledger…</div>';try{const cardId=state.specialLedgerCard||((state.specialCards||[]).find(c=>c.active!==false&&((isManagementUser()&&state.selectedLocation==='all')||(c.assignedLocationIds||[]).includes(isManagementUser()?state.selectedLocation:state.user.locationId)))||{}).id;if(!cardId){el.innerHTML='<div class="hint">No special ledgers are assigned to this location.</div>';return}state.specialLedgerCard=cardId;const from=document.getElementById('slFrom')?.value||monthKeyOf(todayStr())+'-01',to=document.getElementById('slTo')?.value||todayStr(),locationId=isManagementUser()?(document.getElementById('slLocation')?.value||state.selectedLocation):state.user.locationId,username=isManagementUser()?(document.getElementById('slUser')?.value||'all'):'all';specialLedgerData=await api('/api/special-ledger?'+new URLSearchParams({cardId,from,to,locationId,username}));renderSpecialLedgerBody()}catch(e){el.innerHTML='<div class="warning">Could not load ledger. '+escapeHtml(e.message||'Please try again.')+'</div>'}}
function renderSpecialLedgerBody(){const el=document.getElementById('specialLedgerBody');if(!el||!specialLedgerData)return;const d=specialLedgerData,rows=d.bookings||[],pays=d.payments||[],totalDue=rows.reduce((a,r)=>a+Number(r.amount||0),0),totalPaid=rows.reduce((a,r)=>a+Number(r.paid||0),0),out=rows.reduce((a,r)=>a+Number(r.pending||0),0);el.innerHTML=`<div class="kpi-grid"><div class="kpi"><div class="label">Total Due</div><div class="value">${money(totalDue)}</div></div><div class="kpi"><div class="label">Received</div><div class="value pos">${money(totalPaid)}</div></div><div class="kpi"><div class="label">Outstanding</div><div class="value neg">${money(out)}</div></div></div><div class="card" style="margin-top:12px"><div class="section-head purple"><div class="section-title-left"><span class="section-icon">▤</span><span>Due Ledger</span></div><button class="btn secondary no-print" onclick="downloadSpecialLedgerCSV()">Download CSV</button></div><div class="hint" style="margin-bottom:8px">Select pending slips below for one combined receipt.</div><table><thead><tr><th></th><th>Due Date</th><th>Slip / Detail</th><th>Entered By</th><th class="amt">Due</th><th class="amt">Received</th><th class="amt">Balance</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.pending>0?`<input type="checkbox" class="sl-check" value="${escapeHtml(r.id)}" data-amount="${r.pending}" onchange="updateBulkTotal()">`:''}</td><td>${fmtDate(r.date)}</td><td>${escapeHtml(r.note||'—')}</td><td>${escapeHtml(r.enteredByName||r.name||'—')}</td><td class="amt">${money(r.amount)}</td><td class="amt pos">${money(r.paid)}</td><td class="amt neg">${money(r.pending)}</td><td>${r.pending>0?'Pending':'Paid'}</td></tr>`).join('')||'<tr><td colspan="8">No dues in selected range.</td></tr>'}</tbody></table><div class="add-row no-print" style="margin-top:10px"><strong id="bulkTotal">Selected: 0 | Total: Rs 0</strong><button class="btn" onclick="bulkReceiveSpecial()">Receive Selected</button></div></div><div class="card" style="margin-top:12px"><div class="section-head blue"><div class="section-title-left"><span class="section-icon">↳</span><span>Receiving Ledger</span></div></div><table><thead><tr><th>Payment Date</th><th>Slip</th><th>Amount</th><th>Received By</th><th>Remarks</th></tr></thead><tbody>${pays.map(p=>`<tr><td>${fmtDate(p.date)}</td><td>${fmtDate(p.bookingDate)} — ${escapeHtml(p.bookingNote||'')}</td><td class="amt pos">${money(p.amount)}</td><td>${escapeHtml(p.name||p.username||'—')}</td><td>${escapeHtml(p.note||'')}</td></tr>`).join('')||'<tr><td colspan="5">No payments in selected range.</td></tr>'}</tbody></table></div>`}
function renderSpecialLedgers(){const cards=(state.specialCards||[]).filter(c=>c.active!==false&&((isManagementUser()&&state.selectedLocation==='all')||(c.assignedLocationIds||[]).includes(isManagementUser()?state.selectedLocation:state.user.locationId)));return `<div class="page-head"><div><h1 class="page-title">Special Ledgers</h1><div class="page-subtitle">Due and receiving ledgers for Ameen, Zakaat and other assigned special cards</div></div></div><div class="card"><div class="filters"><label>Special Card</label><select onchange="state.specialLedgerCard=this.value;loadSpecialLedger()">${cards.map(c=>`<option value="${c.id}" ${state.specialLedgerCard===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')||'<option value="">No cards assigned</option>'}<label>From</label><input type="date" id="slFrom" value="${state.specialLedgerFrom||monthKeyOf(todayStr())+'-01'}"><label>To</label><input type="date" id="slTo" value="${state.specialLedgerTo||todayStr()}">${isManagementUser()?`<select id="slLocation"><option value="all">All locations</option>${state.locations.map(l=>`<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')}</select><select id="slUser"><option value="all">All staff</option>${state.staff.filter(u=>u.role==='staff').map(u=>`<option value="${escapeHtml(u.username)}">${escapeHtml(u.name)}</option>`).join('')}</select>`:''}<button class="btn" onclick="state.specialLedgerFrom=document.getElementById('slFrom').value;state.specialLedgerTo=document.getElementById('slTo').value;loadSpecialLedger()">Apply</button></div></div><div id="specialLedgerBody" class="loading">Loading ledger…</div>`}
window.updateBulkTotal=function(){const xs=[...document.querySelectorAll('.sl-check:checked')],t=xs.reduce((a,x)=>a+Number(x.dataset.amount||0),0);const el=document.getElementById('bulkTotal');if(el)el.textContent=`Selected: ${xs.length} | Total: ${money(t)}`};
window.bulkReceiveSpecial=async function(){const ids=[...document.querySelectorAll('.sl-check:checked')].map(x=>x.value);if(!ids.length){showToast('Select at least one pending slip.',true);return}const note=prompt('Payment remarks (optional):','Bulk payment received');if(note===null)return;try{const endpoint=specialLedgerData?.card?.behavior==='ameen'?'/api/ameen/bulk-payment':'/api/special-card-bulk-payment';const body=specialLedgerData?.card?.behavior==='ameen'?{bookingIds:ids,date:todayStr(),note}:{cardId:state.specialLedgerCard,bookingIds:ids,date:todayStr(),note};const r=await api(endpoint,'POST',body);showToast(`${ids.length} slips received — ${money(r.total)}`);await loadSpecialLedger()}catch(e){showToast(e.message,true)}};
window.downloadSpecialLedgerCSV=async function(){try{const d=specialLedgerData,card=d.card,rows=d.bookings||[],pays=d.payments||[];const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const out=[['Card','Location','Due Date','Slip / Detail','Entered By','Due Amount','Received','Balance','Status'].map(esc).join(','),...rows.map(r=>[card.name,locationName(r.locationId),r.date,r.note||'',r.enteredByName||r.name||'',r.amount,r.paid,r.pending,r.pending>0?'Pending':'Paid'].map(esc).join(',')),['','','','','TOTAL',rows.reduce((a,r)=>a+Number(r.amount||0),0),rows.reduce((a,r)=>a+Number(r.paid||0),0),rows.reduce((a,r)=>a+Number(r.pending||0),0),''].map(esc).join(','),['','','','','RECEIVING LEDGER','','','',''].map(esc).join(','),...pays.map(p=>[card.name,locationName(p.locationId),p.date,'Against '+p.bookingDate+' '+(p.bookingNote||''),p.name||p.username||'',0,p.amount,0,'Received'].map(esc).join(','))].join('\n');const blob=new Blob(['\ufeff'+out],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lab-brain-'+card.id+'-ledger-'+(state.specialLedgerFrom||'from')+'-to-'+(state.specialLedgerTo||todayStr())+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){showToast(e.message,true)}};

function financeDepartmentOptions(selected){return ['Laboratory','X-Ray','Ultrasound','ALL'].map(d=>`<option value="${d}" ${selected===d?'selected':''}>${d}</option>`).join('')}
function financeDepartmentOptions(selected){return ['Laboratory','X-Ray','Ultrasound','ALL'].map(d=>`<option value="${d}" ${selected===d?'selected':''}>${d}</option>`).join('')}
function leaveUsage(employee,field,month){let total=0;for(const k of Object.keys(state.financeData?.salaryRecords||{})){const r=state.financeData.salaryRecords[k];if(r&&r.employee===employee&&String(r.month||'')<=month)total+=Number(r[field]||0)}return total}
function renderFinance(){
 const d=state.financeData||{salaries:[],fixedExpenses:[],departmentSummary:[],financeAdjustments:[],employeeLoans:{}}; const profiles=state.employeeProfiles||[]; const month=state.financeMonth; const panel=state.financePanel||'input';
 const salaryData=(d.salaries||[]).filter(r=>state.financeSalaryLocation==='all'||r.locationId===state.financeSalaryLocation);
 const expenseData=(d.fixedExpenses||[]).filter(r=>state.financeExpenseLocation==='all'||r.locationId===state.financeExpenseLocation);
 const adjustmentData=(d.financeAdjustments||[]).filter(r=>state.financeExpenseLocation==='all'||r.locationId===state.financeExpenseLocation);
 const salaryRows=salaryData.map((r,i)=>{const rec=r.record||{};const loanDed=Number(rec.loanDeduction??r.loan?.installment??0);return `<tr><td><strong>${escapeHtml(r.employee)}</strong><div class="entry-sub-detail">${escapeHtml(locationName(r.locationId))} · ${escapeHtml(r.department)}</div></td><td class="amt">${money(r.salary||0)}</td><td class="amt">${money(r.advanceSalary||0)}</td><td><input class="finance-mini-input" type="number" min="0" step="1" id="abs_${i}" value="${rec.absentDays??''}" placeholder="0"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="sick_${i}" value="${rec.sickLeave??''}" placeholder="0"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="casual_${i}" value="${rec.casualLeave??''}" placeholder="0"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="annual_${i}" value="${rec.annualLeave??''}" placeholder="0"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="late_${i}" value="${rec.lateDays??''}" placeholder="0"></td><td><input class="finance-mini-input" type="number" min="0" step="0.01" id="ded_${i}" value="${rec.manualDeduction??''}" placeholder="0"></td><td class="amt neg">${loanDed?`− ${money(loanDed)}`:money(0)}</td><td class="amt"><strong>${money(rec.netSalary||0)}</strong></td><td class="no-print"><button class="btn secondary" onclick="saveSalaryRow(${i})">Save</button> <button class="btn secondary" onclick="printSalarySlip(${i})">Salary Slip</button></td></tr>`}).join('')||'<tr><td colspan="12" class="muted-row">No employees found for this location.</td></tr>';
 const profileRows=(state.employees||[]).map((name,i)=>{const p=profiles.find(x=>x.employee===name)||{employee:name,locationId:state.locations[0]?.id||'',department:'ALL',salary:0,sickLeaveEntitlement:0,casualLeaveEntitlement:0,annualLeaveEntitlement:0};return `<tr><td><strong>${escapeHtml(name)}</strong></td><td><select id="ep_loc_${i}">${state.locations.map(l=>`<option value="${l.id}" ${p.locationId===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></td><td><select id="ep_dep_${i}">${financeDepartmentOptions(p.department)}</select></td><td><input type="number" min="0" step="0.01" id="ep_sal_${i}" value="${Number(p.salary||0)}"></td><td><button class="btn secondary" onclick="saveEmployeeProfile(${i})">Save</button></td></tr>`}).join('')||'<tr><td colspan="5" class="muted-row">No employees in the existing Employees list.</td></tr>';
 const leaveRows=(state.employees||[]).map((name,i)=>{const p=profiles.find(x=>x.employee===name)||{employee:name,locationId:state.locations[0]?.id||'',sickLeaveEntitlement:0,casualLeaveEntitlement:0,annualLeaveEntitlement:0};const loan=d.employeeLoans?.[name]||{};return `<tr><td><strong>${escapeHtml(name)}</strong><div class="entry-sub-detail">${escapeHtml(locationName(p.locationId))}</div></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="sick_ent_${i}" value="${Number(p.sickLeaveEntitlement||0)}"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="casual_ent_${i}" value="${Number(p.casualLeaveEntitlement||0)}"></td><td><input class="finance-mini-input" type="number" min="0" step="1" id="annual_ent_${i}" value="${Number(p.annualLeaveEntitlement||0)}"></td><td><button class="btn secondary" onclick="saveLeaveEntitlements(${i})">Save</button></td><td>${loan.amount?money(loan.amount):'—'}</td><td>${loan.amount?`${money(loan.installment)}/month from ${escapeHtml(loan.startMonth)}`:'—'}</td><td>${loan.amount?`<button class="btn danger" onclick="removeEmployeeLoan('${escapeHtml(name).replace(/'/g,'\\\'')}")">Remove Loan</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="8" class="muted-row">No employees configured.</td></tr>';
 const categoryRows=(state.fixedExpenseCategories||[]).filter(c=>c.active!==false).map((c,i)=>`<tr><td><input id="fc_name_${i}" value="${escapeHtml(c.name)}"></td><td><select id="fc_loc_${i}">${state.locations.map(l=>`<option value="${l.id}" ${c.locationId===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></td><td><select id="fc_dep_${i}">${financeDepartmentOptions(c.department)}</select></td><td><button class="btn secondary" onclick="saveFixedCategory(${i})">Save</button> <button class="btn danger" onclick="removeFixedCategory(${i})">Disable</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted-row">No fixed expense categories created.</td></tr>';
 const fixedRows=expenseData.map((r,i)=>`<tr><td><strong>${escapeHtml(r.name)}</strong></td><td>${escapeHtml(locationName(r.locationId))}</td><td>${escapeHtml(r.department)}</td><td><input class="finance-amount-input" type="number" min="0" step="0.01" id="fx_${i}" value="${Number(r.amount||0)}"></td><td><button class="btn secondary" onclick="saveFixedAmount(${i})">Save</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted-row">No fixed expense categories for this location.</td></tr>';
 const adjRows=adjustmentData.map((a,i)=>`<tr><td><strong>${escapeHtml(a.location)}</strong></td><td>Vendor Payment</td><td><input class="finance-amount-input" type="number" min="0" step="0.01" id="vendor_${i}" value="${Number(a.vendorPayment||0)}"></td><td><button class="btn secondary" onclick="saveFinanceAdjustment('${a.locationId}','vendorPayment',${i})">Save</button></td></tr><tr><td><strong>${escapeHtml(a.location)}</strong></td><td>Referral Doctor Share</td><td><input class="finance-amount-input" type="number" min="0" step="0.01" id="referral_${i}" value="${Number(a.referralDoctorShare||0)}"></td><td><button class="btn secondary" onclick="saveFinanceAdjustment('${a.locationId}','referralDoctorShare',${i})">Save</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted-row">No locations available.</td></tr>';
 const ds=(d.departmentSummary||[]).map(x=>`<tr><td>${escapeHtml(x.location)}</td><td>${escapeHtml(x.department)}</td><td class="amt">${money(x.revenue)}</td><td class="amt neg">− ${money(x.salary)}</td><td class="amt neg">− ${money(x.fixedExpense)}</td><td class="amt neg">− ${money(x.vendorPayment)}</td><td class="amt neg">− ${money(x.referralDoctorShare)}</td><td class="amt neg">− ${money(x.cashCounterExpense)}</td><td class="amt"><strong>${money(x.net)}</strong></td></tr>`).join('')||'<tr><td colspan="9" class="muted-row">No revenue/expense allocation data for this month.</td></tr>';
 const tabs=`<div class="finance-subtabs"><button class="${panel==='settings'?'active':''}" onclick="setFinancePanel('settings')">Settings</button><button class="${panel==='input'?'active':''}" onclick="setFinancePanel('input')">Monthly Input / Processing</button><button class="${panel==='report'?'active':''}" onclick="setFinancePanel('report')">Reports</button></div>`;
 const monthTools=`<div class="filters"><label>Month</label><input type="month" value="${month}" onchange="setFinanceMonth(this.value)"></div>`;
 const locationFilter=(id,value,fn)=>`<div class="filters" style="margin:8px 0 12px"><label>Location</label><select id="${id}" onchange="${fn}(this.value)"><option value="all" ${value==='all'?'selected':''}>All Locations</option>${state.locations.map(l=>`<option value="${l.id}" ${value===l.id?'selected':''}>${escapeHtml(l.name)}</option>`).join('')}</select></div>`;
 let body='';
 if(panel==='settings') body=`<div class="card"><div class="finance-panel-head"><div><h3>Employee Profile & Salary Setup</h3><div class="hint">Set employee location, department and monthly salary once. Employee names always come from Settings → Employees.</div></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Location</th><th>Department</th><th>Monthly Salary</th><th>Action</th></tr></thead><tbody>${profileRows}</tbody></table></div></div><div class="card"><h3>Leave Entitlement & Loan Setup</h3><div class="hint" style="margin-bottom:10px">Set annual leave entitlements. Leave is only recorded; it never creates an automatic salary deduction. Loans are deducted by the configured monthly installment.</div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Sick Leave Assigned</th><th>Casual Leave Assigned</th><th>Annual Leave Assigned</th><th>Leave Action</th><th>Loan Amount</th><th>Monthly Installment / Start</th><th>Loan Action</th></tr></thead><tbody>${leaveRows}</tbody></table></div><div class="card" style="margin-top:10px"><h4>Add / Update Employee Loan</h4><div class="add-row"><select id="loan_employee">${state.employees.map(n=>`<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join('')}</select><input id="loan_amount" type="number" min="0" step="0.01" placeholder="Loan amount"><input id="loan_installment" type="number" min="0" step="0.01" placeholder="Monthly installment"><input id="loan_start" type="month" value="${month}"><input id="loan_remarks" placeholder="Remarks" style="flex:1"><button class="btn secondary" onclick="saveEmployeeLoan()">Save Loan</button></div></div></div><div class="card"><h3>Fixed Expense Categories</h3><div class="hint" style="margin-bottom:10px">Create and configure fixed expenses by location and department. These settings automatically appear in Monthly Input and Reports.</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Location</th><th>Department</th><th>Action</th></tr></thead><tbody>${categoryRows}</tbody></table></div><div class="add-row" style="margin-top:12px"><input id="newFixedName" placeholder="New fixed expense name" style="flex:1"><select id="newFixedLoc">${state.locations.map(l=>`<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')}</select><select id="newFixedDep">${financeDepartmentOptions('ALL')}</select><button class="btn secondary" onclick="addFixedCategory()">Add Category</button></div></div>`;
 else if(panel==='report') body=`<div class="card"><div class="finance-panel-head"><div><h3>Financial Report — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Revenue less Salary, Fixed Expenses, Vendor Payment, Referral Doctor Share and Cash Counter Expenses = Net Profit. No leave-based automatic deductions are applied.</div></div>${monthTools}</div><div class="table-wrap"><table><thead><tr><th>Location</th><th>Department</th><th class="amt">Revenue</th><th class="amt">Salary</th><th class="amt">Fixed Expense</th><th class="amt">Vendor Payment</th><th class="amt">Referral Doctor Share</th><th class="amt">Cash Counter Expense</th><th class="amt">Net Profit</th></tr></thead><tbody>${ds}</tbody></table></div></div>`;
 else body=`<div class="card"><div class="finance-panel-head"><div><h3>Monthly Salary Processing — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Basic Salary − Advance Salary − Manual Deduction − Loan Installment = Net Salary. Absent, Late, Sick, Casual and Annual Leave are recorded only; none creates an automatic deduction.</div></div>${monthTools}</div>${locationFilter('salaryLocationFilter',state.financeSalaryLocation,'setFinanceSalaryLocation')}<div class="table-wrap"><table><thead><tr><th>Employee</th><th class="amt">Basic Salary</th><th class="amt">Advance</th><th>Absent</th><th>Sick</th><th>Casual</th><th>Annual</th><th>Late</th><th>Deduction</th><th class="amt">Loan Deduction</th><th class="amt">Net Salary</th><th class="no-print">Action</th></tr></thead><tbody>${salaryRows}</tbody></table></div></div><div class="card"><div class="finance-panel-head"><div><h3>Monthly Fixed Expense Amounts — ${escapeHtml(fmtMonthLabel(month))}</h3><div class="hint">Enter actual monthly amounts. Location filter also applies to Vendor Payment and Referral Doctor Share below.</div></div></div>${locationFilter('expenseLocationFilter',state.financeExpenseLocation,'setFinanceExpenseLocation')}<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Location</th><th>Department</th><th>Amount</th><th>Action</th></tr></thead><tbody>${fixedRows}</tbody></table></div><h4 style="margin:16px 0 8px">Other Monthly Expenses</h4><div class="table-wrap"><table><thead><tr><th>Location</th><th>Expense Type</th><th>Amount</th><th>Action</th></tr></thead><tbody>${adjRows}</tbody></table></div></div>`;
 return `<div class="card finance-page"><div class="analysis-head"><div><h2>Salary & Fixed Expenses</h2><div class="hint">Manage setup, monthly inputs and generated financial reports in separate sections.</div></div></div>${tabs}${body}</div>`;
}
window.setFinancePanel=function(panel){if(!['settings','input','report'].includes(panel))panel='input';state.financePanel=panel;render()};
async function loadFinance(){try{state.financeData=await api('/api/finance-management?month='+encodeURIComponent(state.financeMonth)+'&locationId=all');state.employeeProfiles=state.financeData.employeeProfiles||state.employeeProfiles;state.fixedExpenseCategories=state.financeData.fixedExpenseCategories||state.fixedExpenseCategories;render()}catch(e){showToast(e.message,true)}}
window.setFinanceMonth=async function(v){if(!v)return;state.financeMonth=v;await loadFinance()};
window.setFinanceSalaryLocation=function(v){state.financeSalaryLocation=v;render()};
window.setFinanceExpenseLocation=function(v){state.financeExpenseLocation=v;render()};
window.saveEmployeeProfile=async function(i){const name=state.employees[i];if(!name)return;const existing=(state.employeeProfiles||[]).find(p=>p.employee===name)||{};const profiles=(state.employeeProfiles||[]).filter(p=>p.employee!==name);profiles.push({employee:name,locationId:document.getElementById('ep_loc_'+i).value,department:document.getElementById('ep_dep_'+i).value,salary:Number(document.getElementById('ep_sal_'+i).value||0),sickLeaveEntitlement:Number(existing.sickLeaveEntitlement||0),casualLeaveEntitlement:Number(existing.casualLeaveEntitlement||0),annualLeaveEntitlement:Number(existing.annualLeaveEntitlement||0),active:true});try{const r=await api('/api/config/employee-profiles','PUT',{employeeProfiles:profiles});state.employeeProfiles=r.employeeProfiles||profiles;showToast('Employee profile saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveLeaveEntitlements=async function(i){const name=state.employees[i];if(!name)return;const existing=(state.employeeProfiles||[]).find(p=>p.employee===name)||{employee:name,locationId:state.locations[0]?.id||'',department:'ALL',salary:0};const profiles=(state.employeeProfiles||[]).filter(p=>p.employee!==name);profiles.push({...existing,sickLeaveEntitlement:Number(document.getElementById('sick_ent_'+i).value||0),casualLeaveEntitlement:Number(document.getElementById('casual_ent_'+i).value||0),annualLeaveEntitlement:Number(document.getElementById('annual_ent_'+i).value||0),active:true});try{const r=await api('/api/config/employee-profiles','PUT',{employeeProfiles:profiles});state.employeeProfiles=r.employeeProfiles||profiles;showToast('Leave entitlement saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveEmployeeLoan=async function(){const employee=document.getElementById('loan_employee')?.value,amount=Number(document.getElementById('loan_amount')?.value||0),installment=Number(document.getElementById('loan_installment')?.value||0),startMonth=document.getElementById('loan_start')?.value,remarks=document.getElementById('loan_remarks')?.value||'';if(!employee||amount<=0||installment<=0||!startMonth){showToast('Enter employee, loan amount, monthly installment and start month.',true);return}try{await api('/api/finance-management/employee-loan','PUT',{employee,amount,installment,startMonth,remarks});showToast('Employee loan saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.removeEmployeeLoan=async function(employee){if(!confirm('Remove this employee loan?'))return;try{await api('/api/finance-management/employee-loan/'+encodeURIComponent(employee),'DELETE',{});showToast('Employee loan removed.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveSalaryRow=async function(i){const r=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation)[i];if(!r)return;try{await api('/api/finance-management/salary','PUT',{month:state.financeMonth,employee:r.employee,absentDays:Number(document.getElementById('abs_'+i).value||0),sickLeave:Number(document.getElementById('sick_'+i).value||0),casualLeave:Number(document.getElementById('casual_'+i).value||0),annualLeave:Number(document.getElementById('annual_'+i).value||0),lateDays:Number(document.getElementById('late_'+i).value||0),manualDeduction:Number(document.getElementById('ded_'+i).value||0)});showToast('Salary saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveFixedAmount=async function(i){const rows=(state.financeData?.fixedExpenses||[]).filter(x=>state.financeExpenseLocation==='all'||x.locationId===state.financeExpenseLocation),r=rows[i];if(!r)return;try{await api('/api/finance-management/fixed-expense','PUT',{month:state.financeMonth,categoryId:r.id,amount:Number(document.getElementById('fx_'+i).value||0)});showToast('Fixed expense saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveFinanceAdjustment=async function(locationId,type,i){const id=type==='vendorPayment'?'vendor_'+i:'referral_'+i;const amount=Number(document.getElementById(id)?.value||0);try{await api('/api/finance-management/adjustment','PUT',{month:state.financeMonth,locationId,type,amount});showToast(type==='vendorPayment'?'Vendor payment saved.':'Referral doctor share saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.printSalarySlip=function(i){const rows=(state.financeData?.salaries||[]).filter(x=>state.financeSalaryLocation==='all'||x.locationId===state.financeSalaryLocation),r=rows[i];if(!r)return;const rec=r.record||{},p=(state.employeeProfiles||[]).find(x=>x.employee===r.employee)||r,basic=Number(rec.basicSalary||r.salary||0),adv=Number(rec.advanceSalary||r.advanceSalary||0),ded=Number(rec.manualDeduction||0),loanDed=Number(rec.loanDeduction??r.loan?.installment??0),net=Number(rec.netSalary||Math.max(0,basic-adv-ded-loanDed)),sickEnt=Number(p.sickLeaveEntitlement||0),casualEnt=Number(p.casualLeaveEntitlement||0),annualEnt=Number(p.annualLeaveEntitlement||0),sickUsed=leaveUsage(r.employee,'sickLeave',state.financeMonth),casualUsed=leaveUsage(r.employee,'casualLeave',state.financeMonth),annualUsed=leaveUsage(r.employee,'annualLeave',state.financeMonth),sickRem=Math.max(0,sickEnt-sickUsed),casualRem=Math.max(0,casualEnt-casualUsed),annualRem=Math.max(0,annualEnt-annualUsed);const w=window.open('','_blank','width=850,height=950');if(!w){showToast('Please allow pop-ups to print the salary slip.',true);return}w.document.write(`<!doctype html><html><head><title>Salary Slip</title><style>body{font-family:Arial,sans-serif;padding:35px;color:#17324d}h1{text-align:center;margin:0 0 4px}h2{text-align:center;font-size:16px;margin:0 0 20px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 30px;border:1px solid #ccc;padding:12px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.box{border:1px solid #bbb}.box h3{margin:0;padding:8px;background:#f3f6fa;font-size:14px}.row{display:flex;justify-content:space-between;padding:8px 10px;border-bottom:1px solid #ddd}.total{font-weight:700;font-size:17px}.leave{margin-top:20px;border:1px solid #bbb;border-collapse:collapse;width:100%}.leave th,.leave td{border:1px solid #bbb;padding:8px;text-align:center}.sign{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:60px;text-align:center}.line{border-top:1px solid #333;padding-top:6px}small{color:#666}</style></head><body><h1>Lab-Brain</h1><h2>Salary Slip — ${escapeHtml(fmtMonthLabel(state.financeMonth))}</h2><div class="meta"><div><b>Employee:</b> ${escapeHtml(r.employee)}</div><div><b>Location:</b> ${escapeHtml(locationName(r.locationId))}</div><div><b>Department:</b> ${escapeHtml(r.department)}</div><div><b>Pay Period:</b> ${escapeHtml(fmtMonthLabel(state.financeMonth))}</div></div><div class="cols"><div class="box"><h3>Earnings</h3><div class="row"><span>Basic Salary</span><span>${money(basic)}</span></div></div><div class="box"><h3>Deductions</h3><div class="row"><span>Advance Salary</span><span>${money(adv)}</span></div><div class="row"><span>Manual Deduction</span><span>${money(ded)}</span></div><div class="row"><span>Loan Deduction</span><span>${money(loanDed)}</span></div></div></div><div class="row total" style="margin-top:15px;border:1px solid #bbb"><span>Net Salary</span><span>${money(net)}</span></div><table class="leave"><tr><th>Leave Type</th><th>Assigned</th><th>Taken</th><th>Remaining</th></tr><tr><td>Sick Leave</td><td>${sickEnt}</td><td>${sickUsed}</td><td>${sickRem}</td></tr><tr><td>Casual Leave</td><td>${casualEnt}</td><td>${casualUsed}</td><td>${casualRem}</td></tr><tr><td>Annual Leave</td><td>${annualEnt}</td><td>${annualUsed}</td><td>${annualRem}</td></tr></table><div class="cols"><div class="box"><h3>Attendance / Record</h3><div class="row"><span>Absent</span><span>${Number(rec.absentDays||0)} day(s)</span></div><div class="row"><span>Late</span><span>${Number(rec.lateDays||0)} day(s)</span></div><div class="row"><span>Sick Leave</span><span>${Number(rec.sickLeave||0)} day(s)</span></div><div class="row"><span>Casual Leave</span><span>${Number(rec.casualLeave||0)} day(s)</span></div><div class="row"><span>Annual Leave</span><span>${Number(rec.annualLeave||0)} day(s)</span></div></div><div class="box"><h3>Loan</h3><div class="row"><span>Total Loan</span><span>${money(r.loan?.amount||0)}</span></div><div class="row"><span>Monthly Installment</span><span>${money(loanDed)}</span></div><div class="row"><span>Balance After This Month</span><span>${money(rec.loanRemainingAfter??r.loan?.remaining??0)}</span></div></div></div><div class="sign"><div class="line">Employer Signature</div><div class="line">Employee Signature</div></div><p style="text-align:center;margin-top:35px"><small>This is a system generated payslip.</small></p><script>window.onload=function(){window.print();}<\/script></body></html>`);w.document.close()};

window.addFixedCategory=async function(){const name=document.getElementById('newFixedName').value.trim();if(!name){showToast('Enter a fixed expense name.',true);return}const arr=[...(state.fixedExpenseCategories||[]),{id:'fixed_'+Date.now(),name,locationId:document.getElementById('newFixedLoc').value,department:document.getElementById('newFixedDep').value,active:true}];try{const r=await api('/api/config/fixed-expense-categories','PUT',{fixedExpenseCategories:arr});state.fixedExpenseCategories=r.fixedExpenseCategories||arr;showToast('Fixed expense category added.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.saveFixedCategory=async function(i){const active=(state.fixedExpenseCategories||[]).filter(c=>c.active!==false),c=active[i];if(!c)return;c.name=document.getElementById('fc_name_'+i).value.trim();c.locationId=document.getElementById('fc_loc_'+i).value;c.department=document.getElementById('fc_dep_'+i).value;try{const all=[...(state.fixedExpenseCategories||[])].map(x=>x.id===c.id?c:x);const r=await api('/api/config/fixed-expense-categories','PUT',{fixedExpenseCategories:all});state.fixedExpenseCategories=r.fixedExpenseCategories||all;showToast('Fixed expense category saved.');await loadFinance()}catch(e){showToast(e.message,true)}};
window.removeFixedCategory=async function(i){const active=(state.fixedExpenseCategories||[]).filter(c=>c.active!==false),c=active[i];if(!c||!confirm('Disable this fixed expense category? Existing monthly amounts will remain saved.'))return;const all=[...(state.fixedExpenseCategories||[])].map(x=>x.id===c.id?{...x,active:false}:x);try{const r=await api('/api/config/fixed-expense-categories','PUT',{fixedExpenseCategories:all});state.fixedExpenseCategories=r.fixedExpenseCategories||all;showToast('Category disabled.');await loadFinance()}catch(e){showToast(e.message,true)}};

(async()=>{try{const ok=await tryResume();if(ok){state.loading=true;render();await loadEverything()}else{state.loading=false;render()}}catch(e){console.error('Startup failed:',e);state.token=null;state.user=null;localStorage.removeItem('labbrain_token');localStorage.removeItem('roznamcha_token');state.loading=false;state.loginError='Unable to load the previous session. Please log in again.';render()}})();
